#include "nestsettings.h"
#include "nestswitch.h"
#include "qvapplication.h"
#include <QtWidgets>
#include <functional>

void showNestSettings(QWidget *parent) {
    for(auto widget:QApplication::topLevelWidgets())if(widget->objectName()=="nestPreferences"){widget->show();widget->raise();widget->activateWindow();return;}
    auto dialog=new QDialog(parent);dialog->setObjectName("nestPreferences");dialog->setAttribute(Qt::WA_DeleteOnClose);dialog->setWindowTitle("NestView 설정");dialog->resize(872,600);
    dialog->setStyleSheet("QDialog{background:white;color:#263a33;} QLabel{color:#263a33;background:transparent;font-size:13px;} QListWidget{background:#f0f3f0;color:#3d4943;border:0;outline:0;font-size:13px;} QListWidget::item{padding:14px 18px;} QListWidget::item:selected{background:#dbe9e1;color:#234b3d;} QStackedWidget,QScrollArea,QScrollArea>QWidget>QWidget{background:white;border:0;} QCheckBox{color:#263a33;spacing:10px;padding:12px 0;} QCheckBox::indicator{width:30px;height:17px;border:1px solid #b6bec4;border-radius:9px;background:#fff;} QCheckBox::indicator:checked{background:#50816c;border-color:#50816c;} QPushButton{padding:7px 18px;background:#f6f8fa;color:#123953;border:1px solid #ccd4dc;border-radius:7px;} QPushButton#confirm{background:#50816c;color:white;border:0;min-width:60px;} QComboBox,QSpinBox,QDoubleSpinBox,QKeySequenceEdit{color:#163a52;background:white;border:1px solid #c0cad2;padding:4px;} QTableWidget{background:white;color:#163a52;border:1px solid #dce3e8;gridline-color:#e9edf0;} QHeaderView::section{background:#f6f9fc;color:#24475b;border:0;padding:6px;}");
    auto root=new QVBoxLayout(dialog);root->setContentsMargins(0,0,22,16);auto body=new QHBoxLayout;body->setSpacing(22);root->addLayout(body,1);
    auto sidebar=new QListWidget(dialog);sidebar->setFixedWidth(182);body->addWidget(sidebar);
    auto stack=new QStackedWidget(dialog);body->addWidget(stack,1);
    auto saves=std::make_shared<QList<std::function<void()>>>();
    auto page=[&](const QString &name,const QString &title){sidebar->addItem(name);auto scroll=new QScrollArea(stack);scroll->setWidgetResizable(true);auto pane=new QWidget(scroll);auto layout=new QVBoxLayout(pane);layout->setContentsMargins(0,20,10,8);layout->setSpacing(8);auto heading=new QLabel(title,pane);heading->setStyleSheet("font-size:21px;font-weight:600;padding-bottom:14px;");layout->addWidget(heading);scroll->setWidget(pane);stack->addWidget(scroll);return layout;};
    auto toggle=[&](QVBoxLayout *layout,const QString &text,const QString &key,bool fallback){auto container=new QWidget(dialog);auto line=new QHBoxLayout(container);line->setContentsMargins(0,10,0,10);line->addWidget(new QLabel(text,container),1);auto row=new NestSwitch(container);row->setAccessibleName(text);row->setChecked(QSettings().value(key,fallback).toBool());line->addWidget(row);layout->addWidget(container);auto divider=new QFrame(dialog);divider->setFixedHeight(1);divider->setStyleSheet("background:#e8edf1;");layout->addWidget(divider);saves->append([row,key]{QSettings().setValue(key,row->isChecked());});};
    auto select=[&](QVBoxLayout *layout,const QString &text,const QString &key,const QStringList &items,int fallback){auto row=new QHBoxLayout;row->addWidget(new QLabel(text,dialog),1);auto combo=new QComboBox(dialog);combo->addItems(items);combo->setCurrentIndex(QSettings().value(key,fallback).toInt());row->addWidget(combo);layout->addLayout(row);saves->append([combo,key]{QSettings().setValue(key,combo->currentIndex());});};
    auto general=page("일반","일반 설정");toggle(general,"ESC키로 창 닫기","nest/escapeCloses",false);toggle(general,"파일 삭제 시 한 번 더 확인하기","options/askdelete",true);toggle(general,"최근 열어본 파일 기억하기","options/saverecents",true);toggle(general,"마지막 창을 닫으면 프로그램 종료","options/quitonlastwindow",false);toggle(general,"마지막 이미지에서 처음으로 돌아가기","options/loopfoldersenabled",true);general->addStretch();
    auto view=page("보기","보기 설정");select(view,"이미지 열 때 창 크기", "options/windowresizemode",{"변경 안함","처음 열 때 맞춤","항상 맞춤"},0);select(view,"제목 표시줄 정보","options/titlebarmode",{"앱 이름","파일 이름","파일 순서 + 이름","파일 정보 모두"},1);toggle(view,"작은 이미지도 창에 맞춰 확대","options/pastactualsizeenabled",true);toggle(view,"전체 화면에서 파일 정보 표시","options/fullscreendetails",false);auto bg=new QPushButton("배경 색상…",dialog);view->addWidget(bg);QObject::connect(bg,&QPushButton::clicked,dialog,[dialog]{auto c=QColorDialog::getColor(QColor(QSettings().value("options/bgcolor","#202020").toString()),dialog);if(c.isValid()){QSettings().setValue("options/bgcolor",c.name());qvApp->getSettingsManager().loadSettings();}});view->addStretch();
    auto processing=page("▧  영상 처리","영상 처리");toggle(processing,"부드러운 이미지 표시","options/filteringenabled",true);toggle(processing,"고품질 축소","options/scalingenabled",true);select(processing,"색상 프로파일 변환","options/colorspaceconversion",{"변환 안함","모니터 프로파일","sRGB","Display P3"},1);select(processing,"다음 이미지 미리 읽기","options/preloadingmode",{"사용 안함","기본 · 최대 250 MiB 캐시","확장 · 최대 약 2 GiB 캐시"},1);toggle(processing,"색상 반전 (정지 이미지)","nest/effects/invert",false);toggle(processing,"흑백 (정지 이미지)","nest/effects/grayscale",false);toggle(processing,"세피아 (정지 이미지)","nest/effects/sepia",false);processing->addStretch();
    auto extensions=page("확장자","지원 이미지 확장자");auto formats=new QLabel(qvApp->getFileExtensionList().join("  "),dialog);formats->setWordWrap(true);extensions->addWidget(formats);auto limitation=new QLabel("RAW·PSD·HEIC는 macOS ImageIO 디코더 지원 범위에 따라 달라집니다.\nHDR 출력과 CLIP 전용 디코더는 이 빌드에 포함되지 않습니다.\n파일 연결은 Finder → 정보 가져오기 → 다음으로 열기에서 지정할 수 있습니다.",dialog);limitation->setWordWrap(true);extensions->addWidget(limitation);extensions->addStretch();
    auto keyboard=page("키보드","키보드 설정");auto table=new QTableWidget(dialog);table->setColumnCount(2);table->setHorizontalHeaderLabels({"기능","기본 단축키"});table->horizontalHeader()->setSectionResizeMode(0,QHeaderView::Stretch);table->horizontalHeader()->setSectionResizeMode(1,QHeaderView::ResizeToContents);table->verticalHeader()->hide();keyboard->addWidget(table,1);
    struct KeyRow {QString settingsKey;QString actionKey;QString custom;QKeySequenceEdit *edit;QKeySequence original;};auto keys=std::make_shared<QList<KeyRow>>();
    auto keyRow=[&](const QString &name,const QString &settingsKey,const QString &actionKey,const QString &custom,const QKeySequence &key){int row=table->rowCount();table->insertRow(row);auto label=new QTableWidgetItem(name);label->setFlags(Qt::ItemIsEnabled);table->setItem(row,0,label);auto edit=new QKeySequenceEdit(key,table);table->setCellWidget(row,1,edit);keys->append({settingsKey,actionKey,custom,edit,key});};
    for(const auto &s:qvApp->getShortcutManager().getShortcutsList())keyRow(s.readableName,"shortcuts/"+s.name,s.name,"",QKeySequence(s.shortcuts.value(0)));
    if(auto window=qvApp->getMainWindow(false))for(auto a:window->actions())if(a->property("nestShortcutId").isValid()&&!a->shortcut().isEmpty())keyRow(a->text(),"nest/shortcuts/"+a->property("nestShortcutId").toString(),"",a->property("nestShortcutId").toString(),a->shortcut());
    auto mouse=page("마우스 및 트랙패드","마우스 및 트랙패드");select(mouse,"마우스 휠","nest/wheelAction",{"이전 / 다음 이미지","확대한 이미지 스크롤","확대 / 축소"},0);select(mouse,"트랙패드 두 손가락 스크롤","nest/trackpadAction",{"이미지 이동 · 맞춤 상태에서 넘기기","항상 이전 / 다음 이미지","이미지 이동만"},0);select(mouse,"스크롤 입력 장치","nest/scrollDevice",{"자동 구분","마우스로 처리","트랙패드로 처리"},0);toggle(mouse,"하단에 커서를 대면 폴더 썸네일 표시","nest/hoverThumbnails",true);toggle(mouse,"마우스 커서 위치를 중심으로 확대","options/cursorzoom",true);toggle(mouse,"확대 시 세밀한 단계 사용","options/fractionalzoom",false);mouse->addWidget(new QLabel("⌘ + 휠은 확대 / 축소합니다. 마우스 휠은 누적 대기 없이 바로 이미지를 넘깁니다.\n트랙패드: 핀치로 확대, 두 손가락으로 확대된 이미지 이동.\n창에 맞춘 상태에서는 짧게 쓸어 넘기고 계속 쓸면 연속 이동합니다.\n자동 구분이 맞지 않는 장치는 위에서 직접 지정할 수 있습니다.\n갤러리: 핀치 또는 Control+휠로 크기를 조절합니다.\n웹툰 보기에서 휠은 위아래 스크롤로 동작합니다.",dialog));mouse->addStretch();
    auto bookmark=page("♧  북마크","북마크 설정");bookmark->addWidget(new QLabel("B 키로 현재 이미지 또는 압축파일을 북마크에 추가합니다.\n북마크 목록은 상단 북마크 패널에서 열 수 있습니다.",dialog));auto clear=new QPushButton("북마크 모두 삭제",dialog);bookmark->addWidget(clear);QObject::connect(clear,&QPushButton::clicked,dialog,[]{QSettings().remove("nest/bookmarks");});bookmark->addStretch();
    auto photo=page("보관 폴더","보관 폴더");auto pathLabel=new QLabel(QSettings().value("nest/photoFolder","설정된 폴더 없음").toString(),dialog);pathLabel->setWordWrap(true);photo->addWidget(pathLabel);auto pick=new QPushButton("보관 폴더 선택…",dialog);photo->addWidget(pick);QObject::connect(pick,&QPushButton::clicked,dialog,[dialog,pathLabel]{auto path=QFileDialog::getExistingDirectory(dialog,"보관 폴더");if(!path.isEmpty()){QSettings().setValue("nest/photoFolder",path);pathLabel->setText(path);}});photo->addStretch();
    auto other=page("기타","파일 목록 설정");select(other,"정렬 방식","options/sortmode",{"파일명","수정 날짜","생성 날짜","파일 크기","파일 형식","무작위"},0);toggle(other,"내림차순 정렬","options/sortdescending",false);toggle(other,"숨김 파일 건너뛰기","options/skiphidden",true);toggle(other,"같은 이름의 RAW + JPG 묶기 (JPG 우선)","nest/groupRawJpeg",false);other->addStretch();
    auto language=page("언어 설정","언어 설정");language->addWidget(new QLabel("NestView의 추가 UI는 현재 한국어로 제공됩니다.\n원본 qView 메뉴의 언어는 기존 번역 리소스를 사용합니다.",dialog));language->addStretch();
    QObject::connect(sidebar,&QListWidget::currentRowChanged,stack,&QStackedWidget::setCurrentIndex);sidebar->setCurrentRow(0);
    auto bottom=new QHBoxLayout;bottom->addStretch();auto confirm=new QPushButton("확인",dialog);confirm->setObjectName("confirm");confirm->setDefault(true);bottom->addWidget(confirm);root->addLayout(bottom);
    QObject::connect(confirm,&QPushButton::clicked,dialog,[dialog,saves,keys]{
        QHash<QString,QString> used;
        for(const auto &row:*keys){auto key=row.edit->keySequence();if(key.isEmpty())continue;QString value=key.toString();if(used.contains(value)&&key!=row.original){QMessageBox::warning(dialog,"단축키 충돌","이미 사용 중인 단축키: "+value);return;}used.insert(value,row.settingsKey);}
        for(auto save:*saves)save();
        for(const auto &row:*keys)if(row.edit->keySequence()!=row.original){if(row.custom.isEmpty())QSettings().setValue(row.settingsKey,QStringList{row.edit->keySequence().toString()});else{QSettings().setValue(row.settingsKey,row.edit->keySequence().toString());for(auto widget:QApplication::topLevelWidgets())for(auto a:widget->actions())if(a->property("nestShortcutId").toString()==row.custom)a->setShortcut(row.edit->keySequence());}}
        qvApp->getSettingsManager().loadSettings();qvApp->getSettingsManager().settingsUpdated();qvApp->getShortcutManager().updateShortcuts();
        for(auto widget:QApplication::topLevelWidgets())if(auto window=qobject_cast<MainWindow *>(widget))if(auto view=window->findChild<QVGraphicsView *>())view->refreshFileList();
        dialog->accept();
    });
    dialog->show();
}
